import { readdir } from "node:fs/promises";
import { resolve } from "node:path";
import { build } from "esbuild";

const root = resolve("supabase/functions");

// Auto-generated by @lovable.dev/mcp-js (Vite plugin). It imports Deno-only
// `npm:` and `https:` specifiers that esbuild cannot resolve in Node, and it is
// rewritten on every build — validating it here is redundant with the plugin's
// own build and produces cross-platform (Windows/CI) resolution failures.
// The file is owned by the plugin and re-emitted from src/lib/mcp/.
const GENERATED_SKIP = new Set(["mcp"]);

const dirs = (await readdir(root, { withFileTypes: true })).filter(
  (entry) => entry.isDirectory() && !entry.name.startsWith("_"),
);

const entries = dirs
  .filter((entry) => !GENERATED_SKIP.has(entry.name))
  .map((entry) => resolve(root, entry.name, "index.ts"));

const skipped = dirs.filter((entry) => GENERATED_SKIP.has(entry.name)).map((e) => e.name);

for (const entryPoint of entries) {
  await build({
    entryPoints: [entryPoint],
    bundle: true,
    platform: "neutral",
    format: "esm",
    external: ["https://*", "npm:*", "jsr:*", "node:*"],
    write: false,
    logLevel: "warning",
  });
}

console.log(
  `Validated ${entries.length} Supabase Edge Function bundles.` +
    (skipped.length ? ` Skipped generated: ${skipped.join(", ")}.` : ""),
);
